// --- 1. Target 接口与 Adaptee ---
public interface Target {
    void request();
}

public class Adaptee {
    public void specificRequest() {
        System.out.println("Adaptee.specificRequest 执行");
    }
}

// --- 2. 类适配器：继承复用 ---
public class ClassAdapter extends Adaptee implements Target {
    @Override
    public void request() {
        // 直接调用继承来的 specificRequest，零转发开销
        specificRequest();
    }
}

// --- 3. 对象适配器：组合复用 ---
public class ObjectAdapter implements Target {
    private final Adaptee adaptee;

    public ObjectAdapter(Adaptee adaptee) {
        this.adaptee = adaptee;
    }

    @Override
    public void request() {
        // 转发给持有的 adaptee 引用
        adaptee.specificRequest();
    }
}

// --- 4. 调用方 ---
public class Client {
    public static void main(String[] args) {
        // 类适配器
        Target classTarget = new ClassAdapter();
        classTarget.request();

        // 对象适配器（运行时可替换 adaptee）
        Target objectTarget = new ObjectAdapter(new Adaptee());
        objectTarget.request();
    }
}

